class PriorityQueue {
    constructor(compare) {
        this.heap = [];
        this.compare = compare;
    }

    enqueue(value) {
        this.heap.push(value);
        this.bubbleUp();
    }

    bubbleUp() {
        let index = this.heap.length - 1;
        while (index > 0) {
            let element = this.heap[index],
                parentIndex = Math.floor((index - 1) / 2),
                parent = this.heap[parentIndex];
            if (this.compare(element, parent) < 0)
                break;
            this.heap[index] = parent;
            this.heap[parentIndex] = element;
            index = parentIndex;
        }
    }

    dequeue() {
        let max = this.heap[0];
        let end = this.heap.pop();
        if (this.heap.length > 0) {
            this.heap[0] = end;
            this.sinkDown(0);
        }
        return max;
    }

    sinkDown(index) {
        let left = 2 * index + 1, right = 2 * index + 2,
            largest = index;

        if (left < this.heap.length
            && this.compare(this.heap[left],
                            this.heap[largest])
                   > 0) {
            largest = left;
        }

        if (right < this.heap.length
            && this.compare(this.heap[right],
                            this.heap[largest])
                   > 0) {
            largest = right;
        }

        if (largest !== index) {
            [this.heap[largest], this.heap[index]] = [
                this.heap[index],
                this.heap[largest],
            ];
            this.sinkDown(largest);
        }
    }

    isEmpty() { return this.heap.length === 0; }
}

function minPoints(points) {
    const m = points.length;
    const n = points[0].length;
    let ans = 0;

    // Initialize priority queue
    const pq = new PriorityQueue(comparator);

    // Push the first vertex (source vertex) with cost as
    // its value
    pq.enqueue([ points[0][0], 0, 0 ]);

    // Dijkstra style loop
    while (!pq.isEmpty()) {

        // Pick the minimum cost item and process its
        // adjacent
        const [cost, x, y] = pq.dequeue();

        // Please note that the ans will either be 0 or
        // negative
        ans = Math.min(ans, cost);

        // Find adjacent of the picked item
        if (x === m - 1 && y === n - 1) {
            break;
        }
        if (x + 1 < m) {
            pq.enqueue(
                [ cost + points[x + 1][y], x + 1, y ]);
        }
        if (y + 1 < n) {
            pq.enqueue(
                [ cost + points[x][y + 1], x, y + 1 ]);
        }
    }

    return Math.abs(ans) + 1;
}

